import React, { useState } from 'react';
import axios from 'axios';
import './LoginPanel.css';

const LoginPanel = () => {
  const [isActive, setIsActive] = useState(false);

  // Login state
  const [loginEmail, setLoginEmail] = useState('');
  const [loginPassword, setLoginPassword] = useState('');
  const [loginError, setLoginError] = useState('');

  // Register state
  const [registerName, setRegisterName] = useState('');
  const [registerEmail, setRegisterEmail] = useState('');
  const [registerPassword, setRegisterPassword] = useState('');
  const [registerError, setRegisterError] = useState('');
  const [registerSuccess, setRegisterSuccess] = useState('');

  const handleRegister = () => setIsActive(true);
  const handleLogin = () => setIsActive(false);

  // Handle login
  const handleLoginSubmit = async (e) => {
    e.preventDefault();
    try {
      const response = await axios.post('http://localhost:8082/api/login', {
        email: loginEmail,
        password: loginPassword
      });

      const { token, role } = response.data;
      localStorage.setItem('token', token);

      if (role === 'admin') {
        window.location.href = '/admin-dashboard';
      } else {
        window.location.href = '/';
      }
    } catch (err) {
      setLoginError('Invalid email or password');
    }
  };

  // Handle admin registration
  const handleRegisterSubmit = async (e) => {
    e.preventDefault();
    try {
      const response = await axios.post('http://localhost:8082/api/register', {
        name: registerName,
        email: registerEmail,
        password: registerPassword,
        role: 'admin'
      });

      setRegisterSuccess('Admin account created successfully!');
      setRegisterError('');
      setIsActive(false);
    } catch (err) {
      setRegisterError(err.response?.data?.message || 'Registration failed');
      setRegisterSuccess('');
    }
  };

  return (
    <div className="login-panel-wrapper">
      <div className={`container ${isActive ? 'active' : ''}`}>

        {/* Sign-Up Form */}
        <div className="form-container sign-up">
          <form onSubmit={handleRegisterSubmit}>
            <div className='logo'>
              <span>e</span>Store
            </div>
            <h1>Create Account</h1>
            <input
              type="text"
              placeholder="Name"
              value={registerName}
              onChange={(e) => setRegisterName(e.target.value)}
              required
            />
            <input
              type="email"
              placeholder="Email"
              value={registerEmail}
              onChange={(e) => setRegisterEmail(e.target.value)}
              required
            />
            <input
              type="password"
              placeholder="Password"
              value={registerPassword}
              onChange={(e) => setRegisterPassword(e.target.value)}
              required
            />
            {registerError && <p style={{ color: 'red' }}>{registerError}</p>}
            {registerSuccess && <p style={{ color: 'green' }}>{registerSuccess}</p>}
            <button type="submit">Sign Up</button>
          </form>
        </div>

        {/* Sign-In Form */}
        <div className="form-container sign-in">
          <form onSubmit={handleLoginSubmit}>
            <div className='logo'>
              <span>e</span>Store
            </div>
            <h1>Log In</h1>
            <input
              type="email"
              placeholder="Email"
              value={loginEmail}
              onChange={(e) => setLoginEmail(e.target.value)}
              required
            />
            <input
              type="password"
              placeholder="Password"
              value={loginPassword}
              onChange={(e) => setLoginPassword(e.target.value)}
              required
            />
            <a href="#">Forget Your Password?</a>
            {loginError && <p style={{ color: 'red' }}>{loginError}</p>}
            <button type="submit">Log In</button>
          </form>
        </div>

        {/* Toggle Panels */}
        <div className="toggle-container">
          <div className="toggle">
            <div className="toggle-panel toggle-left">
              <h1>Welcome Back!</h1>
              <p>Already have an Account</p>
              <button className="hidden" onClick={handleLogin}>Log In</button>
            </div>
            <div className="toggle-panel toggle-right">
              <h1>Hello, Welcome!</h1>
              <p>Don't have an Account?</p>
              <button className="hidden" onClick={handleRegister}>Register</button>
            </div>
          </div>
        </div>

      </div>
    </div>
  );
};

export default LoginPanel;
